public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> Data = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomatoes.", 30),
            new(2, "Spaghetti Carbonara", "Creamy Roman pasta with guanciale, egg yolk, Pecorino Romano, and black pepper.", 25),
            new(3, "Risotto al Funghi", "Slow-stirred Arborio rice with porcini mushrooms and Parmigiano-Reggiano.", 45),
            new(4, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream and cocoa.", 40),
        },
        [2] = new List<Recipe>
        {
            new(5, "Tacos al Pastor", "Marinated pork tacos with pineapple, cilantro, and onion on corn tortillas.", 60),
            new(6, "Guacamole", "Fresh avocado dip with lime, jalapeño, tomato, and cilantro.", 10),
            new(7, "Chicken Enchiladas", "Corn tortillas stuffed with shredded chicken, smothered in red chili sauce and cheese.", 50),
        },
        [3] = new List<Recipe>
        {
            new(8, "Pad Thai", "Stir-fried rice noodles with shrimp, tofu, peanuts, bean sprouts, and tamarind sauce.", 35),
            new(9, "Green Curry", "Aromatic Thai green curry with chicken, bamboo shoots, and Thai basil in coconut milk.", 40),
            new(10, "Tom Yum Soup", "Hot and sour soup with shrimp, lemongrass, galangal, and kaffir lime leaves.", 25),
            new(11, "Mango Sticky Rice", "Sweet glutinous rice topped with ripe mango slices and coconut cream.", 50),
            new(12, "Som Tum", "Spicy green papaya salad with peanuts, dried shrimp, and lime dressing.", 15),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow backend API call.
        await Task.Delay(2000, cancellationToken);

