@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject NavigationManager Nav
@inject ILogger<Recipes> Logger

<PageTitle>Recipes</PageTitle>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <div class="alert alert-info py-1 px-2 d-inline-block" role="status">Refreshing…</div>
    }

    <h3>Recipes — Cuisine @CuisineId</h3>

    @if (_displayedRecipes.Count == 0)
    {
        <p>No recipes found for this cuisine.</p>
    }
    else
    {
        <ul class="list-group">
            @foreach (var recipe in _displayedRecipes)
            {
                <li class="list-group-item">
                    <h5>@recipe.Title</h5>
                    <p class="mb-1">@recipe.Description</p>
                    <small class="text-muted">Prep time: @recipe.PrepTimeMinutes min</small>
                </li>
            }
        </ul>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery(Name = "sort")] public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private List<Recipe> _displayedRecipes = new();
    private bool _isRefreshing;
    private string? _error;

    private int _loadedCuisineId;
    private CancellationTokenSource? _loadCts;
    private CancellationTokenSource _disposeCts = new();

    protected override Task OnInitializedAsync() => LoadRecipesAsync();

    public override Task SetParametersAsync(ParameterView parameters)
    {
        var previousCuisineId = CuisineId;
        var previousSort = Sort;

        base.SetParametersAsync(parameters);

        // Only reload data when the cuisine actually changed, not on sort-only changes.
        if (CuisineId != previousCuisineId && previousCuisineId != 0)
        {
            _ = LoadRecipesAsync();
        }
        else if (Sort != previousSort && _recipes is not null)
        {
            _displayedRecipes = ApplySort(_recipes);
            StateHasChanged();
        }

        return Task.CompletedTask;
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load for a previous cuisine.
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
        }

        _loadCts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);

        _error = null;
        _isRefreshing = _recipes is not null;
        StateHasChanged();

        try
        {
            var recipes = await RecipeService.GetByCuisineAsync(CuisineId, _loadCts.Token);

            _recipes = recipes;
            _displayedRecipes = ApplySort(recipes);
            _loadedCuisineId = CuisineId;
            _isRefreshing = false;
            _error = null;
        }
        catch (OperationCanceledException) when (_disposeCts.IsCancellationRequested)
        {
            // Component is being disposed — stop silently.
        }
        catch (OperationCanceledException)
        {
            // A newer load superseded this one — stop silently.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _error = "The request timed out. Please try again.";
            _isRefreshing = false;
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _error = "Something went wrong while loading recipes. Please try again.";
            _isRefreshing = false;
        }
        finally
        {
            StateHasChanged();
        }
    }

    private Task RetryAsync() => LoadRecipesAsync();

    private List<Recipe> ApplySort(List<Recipe> recipes) => (Sort?.ToLowerInvariant()) switch
    {
        "newest" => recipes.OrderByDescending(r => r.Id).ToList(),
        "popular" => recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
        _ => recipes.ToList(),
    };

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Dispose();
    }
}

