10. @if (_error is not null)
11. {
12.     <div class="alert alert-danger" role="alert">
13.         <p>@_error</p>
14.         <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
15.     </div>
16. }
17. else if (_recipes is null)
18. {
19.     <p><em>Loading recipes…</em></p>
20. }
21. else
22. {
23.     @if (_isRefreshing)
24.     {
25.         <div class="alert alert-info py-1 px-2 d-inline-block" role="status">Refreshing…</div>
26.     }
27. 
28.     <h3>Recipes — Cuisine @CuisineId</h3>
29. 
30.     @if (_displayedRecipes.Count == 0)
31.     {
32.         <p>No recipes found for this cuisine.</p>
33.     }
34.     else
35.     {
