49. @code {
50.     [Parameter] public int CuisineId { get; set; }
51.     [SupplyParameterFromQuery(Name = "sort")] public string? Sort { get; set; }
52. 
53.     private List<Recipe>? _recipes;
54.     private List<Recipe> _displayedRecipes = new();
55.     private bool _isRefreshing;
56.     private string? _error;
57. 
58.     private int _lastLoadedCuisineId;
59.     private CancellationTokenSource? _loadCts;
60.     private CancellationTokenSource _disposeCts = new();
61. 
62.     protected override Task OnParametersSetAsync()
63.     {
64.         if (CuisineId != _lastLoadedCuisineId)
65.         {
66.             return LoadRecipesAsync();
67.         }
68. 
69.         // Sort-only change — reorder without refetching.
70.         if (_recipes is not null)
71.         {
72.             _displayedRecipes = ApplySort(_recipes);
73.         }
74. 
75.         return Task.CompletedTask;
76.     }
77. 
78.     private async Task LoadRecipesAsync()
79.     {
80.         // Cancel any in-flight load for a previous cuisine.
81.         if (_loadCts is not null)
82.         {
83.             await _loadCts.CancelAsync();
84.             _loadCts.Dispose();
85.         }
86. 
87.         _loadCts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);
88. 
89.         _error = null;
90.         _isRefreshing = _recipes is not null;
91.         StateHasChanged();
92. 
93.         try
94.         {
95.             var recipes = await RecipeService.GetByCuisineAsync(CuisineId, _loadCts.Token);
96. 
97.             _recipes = recipes;
98.             _displayedRecipes = ApplySort(recipes);
99.             _loadedCuisineId = CuisineId;
100.         }
101.         catch (OperationCanceledException) when (_disposeCts.IsCancellationRequested)
102.         {
103.             // Component is being disposed — stop silently.
104.         }
105.         catch (OperationCanceledException)
106.         {
107.             // A newer load superseded this one — stop silently.
